710→                    width: "40px",
711→                    background: "transparent",
712→                  }}
713→                />
714→
715→                {/* Remove row button */}
716→                <td
717→                  style={{
718→                    borderBottom:
719→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
